from fractions import Fraction

def generate_random_graph(n):
    G = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if random.choice([True, False]):
                G[i][j] = G[j][i] = random.randint(1, 10)
    return G

def is_tropicalizable(G):
    n = len(G)
    for i in range(n):
        for j in range(i + 1, n):
            if G[i][j] == 0:
                return False
    return True

def tropicalize_graph(G):
    n = len(G)
    G_trop = [[math.inf] * n for _ in range(n)]
    for i in range(n):
        G_trop[i][i] = 0
    for i in range(n):
        for j in range(i + 1, n):
            if G[i][j] != 0:
                G_trop[i][j] = G[j][i] = min(G_trop[i][k] + G[k][j] for k in range(n) if k != i and k != j)
    return G_trop

def compute_tropical_homology_classes(G_trop):
    n = len(G_trop)
    visited = [False] * n
    homology_classes = 0

    def dfs(node, path):
        nonlocal homology_classes
        if node in path:
            homology_classes += 1
            return True
        visited[node] = True
        for neighbor in range(n):
            if G_trop[node][neighbor] != math.inf and not visited[neighbor]:
                if dfs(neighbor, path + [node]):
                    return True
        visited[node] = False
        return False

    for i in range(n):
        if not visited[i]:
            dfs(i, [])

    return homology_classes

def construct_arithmetic_circuit(G_trop):
    n = len(G_trop)
    circuit_size = 0

    def find_min_path(start, end):
        nonlocal circuit_size
        min_dist = math.inf
        for k in range(n):
            if G_trop[start][k] != math.inf and G_trop[k][end] != math.inf:
                dist = G_trop[start][k] + G_trop[k][end]
                if dist < min_dist:
                    min_dist = dist
                    circuit_size += 2
        return min_dist

    for i in range(n):
        for j in range(i + 1, n):
            find_min_path(i, j)

    return circuit_size

